begin;
select plan(8);
select ok(not has_table_privilege('authenticated','public.books_native_invoice_request_resolutions','select'),'browser cannot inspect cancellation history directly');
select ok(not has_table_privilege('anon','public.books_native_invoice_request_resolutions','insert'),'anonymous cannot cancel source requests');
select ok(has_table_privilege('service_role','public.books_native_invoice_request_resolutions','select,insert'),'authorized server may append scoped cancellations');
select ok(not has_table_privilege('service_role','public.books_native_invoice_request_resolutions','update,delete'),'cancellations cannot be rewritten');
select ok(not has_function_privilege('authenticated','public.resolve_books_native_invoice_request(uuid,uuid,uuid,uuid,uuid,jsonb,text)','execute'),'browser cannot invoke private resolution RPC');
select ok(has_function_privilege('service_role','public.resolve_books_native_invoice_request(uuid,uuid,uuid,uuid,uuid,jsonb,text)','execute'),'server may invoke scoped resolver');
select ok(not (select prosecdef from pg_proc where oid='public.resolve_books_native_invoice_request(uuid,uuid,uuid,uuid,uuid,jsonb,text)'::regprocedure),'resolver retains invoker authority');
select ok(exists(select 1 from pg_trigger where tgrelid='public.books_native_invoice_postings'::regclass and tgname='zz_books_native_invoice_request_guard'),'direct native receipt insert is fenced against cancellation');
select * from finish();
rollback;
